import math


def owner(point, sites):
    if not sites:
        raise ValueError("no sites")
    best = None
    best_d = None
    for index, site in enumerate(sites):
        d = (site[0] - point[0]) ** 2 + (site[1] - point[1]) ** 2
        if best_d is None or d < best_d - 1e-12:
            best, best_d = [index], d
        elif abs(d - best_d) <= 1e-12:
            best.append(index)
    return sorted(best)


def delaunay_edges(sites, samples, width, height):
    if len(sites) < 2:
        raise ValueError("need at least two sites")
    if samples < 2:
        raise ValueError("need at least two samples per axis")
    edges = set()
    for j in range(samples):
        for i in range(samples):
            x = width * (i + 0.5) / samples
            y = height * (j + 0.5) / samples
            here = owner((x, y), sites)
            if len(here) > 1:
                for a in range(len(here)):
                    for b in range(a + 1, len(here)):
                        edges.add((here[a], here[b]))
                continue
            for dx, dy in ((width / samples, 0.0), (0.0, height / samples)):
                if x + dx > width or y + dy > height:
                    continue
                there = owner((x + dx, y + dy), sites)
                if there[0] != here[0]:
                    edges.add(tuple(sorted((here[0], there[0]))))
    return sorted(edges)


def lloyd(sites, samples, width, height):
    totals = [[0.0, 0.0, 0] for _ in sites]
    for j in range(samples):
        for i in range(samples):
            x = width * (i + 0.5) / samples
            y = height * (j + 0.5) / samples
            index = owner((x, y), sites)[0]
            totals[index][0] += x
            totals[index][1] += y
            totals[index][2] += 1
    moved = []
    for site, (sx, sy, n) in zip(sites, totals):
        moved.append(site if n == 0 else (sx / n, sy / n))
    return moved
